export const getSendNotificationsUrl = () => {
  return `/api/results/notify`;
};

export const sendNotifications = async (
  options?: RequestInit,
): Promise<NotifyResult> => {
  return customFetch<NotifyResult>(getSendNotificationsUrl(), {
    ...options,
    method: "POST",
  });
};

export const getSendNotificationsMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof sendNotifications>>,
    TError,
    void,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof sendNotifications>>,
  TError,
  void,
  TContext
> => {
  const mutationKey = ["sendNotifications"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof sendNotifications>>,
    void
  > = () => {
    return sendNotifications(requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

